import numpy as np
lines=open('opt.xyz').read().split(chr(10))
n=int(lines[0]); at=[];xyz=[]
for l in lines[2:2+n]:
    p=l.split(); at.append(p[0]); xyz.append([float(x) for x in p[1:4]])
xyz=np.array(xyz)
import itertools
# bonds
cov={'C':0.77,'O':0.66,'Se':1.2,'H':0.35}
bonds={i:[] for i in range(n)}
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(xyz[i]-xyz[j])
    if d< (cov[at[i]]+cov[at[j]])*1.3: bonds[i].append(j); bonds[j].append(i)
se=[i for i in range(n) if at[i]=='Se'][0]
print('Se',se,[(k,at[k]) for k in bonds[se]])
for k in bonds[se]:
    print(k,at[k],[(m,at[m]) for m in bonds[k]])
"

